draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W / 2 - 100 + 50 * Math.sin(t), H / 2 - 150 + 20 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 100 + 50 * Math.sin(t + Math.PI), H / 2 - 150 + 20 * Math.cos(t + Math.PI), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // tree
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W / 2 - 20, H / 2 + 50, 40, 100);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 30, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // leaves
  ctx.fillStyle = 'lightgreen';
  ctx.beginPath();
  ctx.arc(W / 2 - 30 + 10 * Math.sin(t), H / 2 - 20 + 10 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 30 + 10 * Math.sin(t + Math.PI), H / 2 - 20 + 10 * Math.cos(t + Math.PI), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
